import assert from 'node:assert/strict';
import {randomUUID,createHash} from 'node:crypto';
import type {Page} from 'playwright';
import type {PrismaClient} from '@prisma/client';
import {dashboardStorageKey,writeDashboardObject} from '../../src/server/storage';
import {waitForBrowserJson} from './browser-poll';
type Quality={activeVersionId:string;checks:{id:string;versionId:string;status:string;issues:{code:string;resolvedAt:string|null}[]}[]};
export async function verifyDataModel(page:Page,origin:string,workspaceId:string,db:PrismaClient,check:(page:Page,phase:string)=>Promise<void>){
 const root=origin+'/dashboard/app/workspaces/'+workspaceId,api='/dashboard/app/api/workspaces/'+workspaceId;
 async function stage(name:string,csv:string){const dataset=await db.dashboardDataset.create({data:{workspaceId,name}}),versionId=randomUUID(),bytes=Buffer.from(csv),key=dashboardStorageKey(workspaceId,dataset.id,versionId);await writeDashboardObject(key,bytes);await db.dashboardDatasetVersion.create({data:{id:versionId,datasetId:dataset.id,version:1,status:'PENDING',sourceFormat:'CSV',storageKey:key,fileSize:BigInt(bytes.length),checksum:createHash('sha256').update(bytes).digest('hex')}});await db.dashboardJob.create({data:{workspaceId,kind:'DATASET_INGEST',idempotencyKey:'browser-stage-'+versionId,payload:{datasetId:dataset.id,versionId,format:'csv'}}});await waitForBrowserJson<{datasets:{id:string;pendingVersionId:string|null;latestVersionId:string|null}[]}>(page,api+'/datasets',r=>r.datasets.some(d=>d.id===dataset.id&&!d.pendingVersionId&&d.latestVersionId===versionId),'Data model fixture profiling');return {datasetId:dataset.id,versionId};}
 await page.setViewportSize({width:1280,height:900});
 const right=await stage('Browser customers','id,label\n001,Alice\n002,Bob\n003,Carol\n');
 await page.goto(root+'/relationships');await page.getByRole('heading',{name:'Dataset relationships',exact:true}).waitFor();await page.getByLabel('Relationship name',{exact:true}).fill('Browser relationship');await page.getByLabel('Left dataset',{exact:true}).selectOption({label:'Browser orders'});await page.getByLabel('Right dataset',{exact:true}).selectOption(right.datasetId);await page.getByRole('button',{name:'Suggest relationships',exact:true}).click();await page.getByRole('button',{name:'Use candidate 1',exact:true}).click();await page.getByRole('button',{name:'Preview join',exact:true}).click();await page.getByText(/Preview: 3 left rows, 3 right rows → 3 output rows/).waitFor();await page.getByLabel('I reviewed the key meanings, cardinality and output counts.',{exact:true}).check();await page.getByRole('button',{name:'Save relationship',exact:true}).click();await page.getByRole('button',{name:'Edit Browser relationship',exact:true}).waitFor();
 await check(page,'dataset-relationships-desktop');await page.setViewportSize({width:390,height:844});await check(page,'dataset-relationships-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Relationship page overflows mobile viewport');await page.setViewportSize({width:1280,height:900});
 await page.getByRole('button',{name:'Edit Browser relationship',exact:true}).click();await page.getByLabel('Relationship name',{exact:true}).fill('Browser relationship revised');await page.getByRole('button',{name:'Preview join',exact:true}).click();await page.getByText(/Preview: 3 left rows/).waitFor();await page.getByLabel('I reviewed the key meanings, cardinality and output counts.',{exact:true}).check();await page.getByRole('button',{name:'Save relationship',exact:true}).click();await page.getByRole('button',{name:'Create dataset from Browser relationship revised',exact:true}).waitFor();page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Create dataset from Browser relationship revised',exact:true}).click();await page.getByText('Join queued.',{exact:false}).waitFor();
 const datasets=await waitForBrowserJson<{datasets:{id:string;name:string;pendingVersionId:string|null;latestVersionId:string|null;metricConfirmationRequired:boolean}[]}>(page,api+'/datasets',r=>r.datasets.some(d=>d.name==='Browser relationship revised joined'&&!d.pendingVersionId&&!!d.latestVersionId),'Joined dataset profiling');const joined=datasets.datasets.find(d=>d.name==='Browser relationship revised joined')!;assert.equal(joined.metricConfirmationRequired,true);assert.ok(datasets.datasets.some(d=>d.name==='Browser orders'));
 page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Delete Browser relationship revised',exact:true}).click();await page.getByText('Relationship deleted.',{exact:true}).waitFor();assert.equal(await db.dashboardDataset.count({where:{workspaceId,id:joined.id}}),1);
 const source=await stage('Browser quality corrections','id,label\n001,Alpha\n001,Alpha\n002,Beta\n'),qualityApi=api+'/datasets/'+source.datasetId+'/quality';
 await page.goto(root+'/data');await page.getByLabel('Dataset to manage',{exact:true}).selectOption(source.datasetId);await page.getByRole('button',{name:'Run data validation',exact:true}).click();await waitForBrowserJson<Quality>(page,qualityApi,r=>r.checks.some(c=>c.status==='FAIL'&&c.issues.some(i=>i.code==='DUPLICATE_ROWS')),'Duplicate validation');await page.getByRole('button',{name:'Refresh quality results',exact:true}).click();await page.getByRole('region',{name:'Source quality',exact:true}).getByText('Source quality: Fail',{exact:true}).waitFor();await page.getByText(/FAIL · Current version/).click();await page.getByRole('button',{name:'Review DUPLICATE_ROWS',exact:true}).click();await page.getByLabel('Review note',{exact:true}).fill('Reviewed duplicate rows; preparing a corrected version.');await page.getByRole('button',{name:'Save quality review',exact:true}).click();await page.getByText('Quality review saved.',{exact:true}).waitFor();
 await check(page,'quality-issue-review-desktop');await page.setViewportSize({width:390,height:844});await check(page,'quality-issue-review-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Quality page overflows mobile viewport');await page.setViewportSize({width:1280,height:900});
 await page.getByLabel('Transformation operation',{exact:true}).selectOption('DROP_DUPLICATES');await page.getByRole('button',{name:'Add transformation step',exact:true}).click();await page.getByRole('button',{name:'Create cleaned version',exact:true}).click();await page.getByText('Transformation queued.',{exact:false}).waitFor();await waitForBrowserJson<{datasets:{id:string;latestVersionId:string|null;pendingVersionId:string|null}[]}>(page,api+'/datasets',r=>r.datasets.some(d=>d.id===source.datasetId&&!d.pendingVersionId&&!!d.latestVersionId&&d.latestVersionId!==source.versionId),'Duplicate correction profiling');
 await page.reload();await page.getByLabel('Dataset to manage',{exact:true}).selectOption(source.datasetId);await page.getByRole('button',{name:'Run data validation',exact:true}).click();const quality=await waitForBrowserJson<Quality>(page,qualityApi,r=>r.checks.some(c=>c.status==='PASS'&&c.versionId===r.activeVersionId),'Corrected version validation');await page.getByRole('button',{name:'Refresh quality results',exact:true}).click();await page.getByRole('region',{name:'Source quality',exact:true}).getByText('Source quality: Pass',{exact:true}).waitFor();await page.getByText(/FAIL · Prior version/).click();await page.getByRole('button',{name:'Review DUPLICATE_ROWS',exact:true}).click();await page.getByLabel('Review decision',{exact:true}).selectOption('RESOLVE_FIXED');await page.getByLabel('Passing validation check',{exact:true}).selectOption(quality.checks.find(c=>c.status==='PASS'&&c.versionId===quality.activeVersionId)!.id);await page.getByLabel('Review note',{exact:true}).fill('Removed exact duplicates; the corrected version passed validation.');await page.getByRole('button',{name:'Save quality review',exact:true}).click();await page.getByText('Quality review saved.',{exact:true}).waitFor();await waitForBrowserJson<Quality>(page,qualityApi,r=>r.checks.some(c=>c.issues.some(i=>i.code==='DUPLICATE_ROWS'&&!!i.resolvedAt)),'Verified issue resolution');
 console.log('PASS: relationship suggestion, preview, create/edit/delete, actual joined dataset and retained sources; quality acknowledgement, duplicate correction, current validation and verified resolution; four desktop/mobile accessibility scans.');
}
